public long[] sumOverSubsets(int n, long[] A) {
    int size = 1 << n;
    long[] F = new long[size];
    for (int m = 0; m < size; m++) {
        int sub = m;
        while (true) {
            F[m] += A[sub];
            if (sub == 0) break;       // processed the empty submask
            sub = (sub - 1) & m;        // next smaller submask
        }
    }
    return F;
}

