def sumOverSubsets(self, n: int, A: list[int]) -> list[int]:
    size = 1 << n
    F = [0] * size
    for m in range(size):
        sub = m
        while True:
            F[m] += A[sub]
            if sub == 0:
                break               # processed the empty submask
            sub = (sub - 1) & m       # next smaller submask
    return F

