public long[] sumOverSubsets(int n, long[] A) {
    int size = 1 << n;
    long[] F = A.clone();
    for (int i = 0; i < n; i++) {
        for (int mask = 0; mask < size; mask++) {
            if ((mask & (1 << i)) != 0) {
                F[mask] += F[mask ^ (1 << i)];
            }
        }
    }
    return F;
}

